import { describe, expect, it } from "@effect/vitest";
import * as path from "node:path";
import { type Member, planSync, type Snapshot } from "@repo/cli/internal/workspace";

const buildConfigFragment = `{
  "extends": "./tsconfig.json",
  "include": ["src"],
  // generated by pkg sync
  "references": []
}
`;

const snapshot = (...members: ReadonlyArray<Member>): Snapshot => ({
  members: [
    {
      dir: "",
      kind: "root",
      manifest: { name: "monorepo", private: true, repo: { npmScope: "@acme" } },
      buildConfig: undefined,
    },
    ...members,
  ],
  fragments: {
    buildConfig: buildConfigFragment,
    manifest: {
      files: ["src/**/*.ts", "dist/**/*.js"],
      scripts: { build: "tsc -b tsconfig.build.json" },
      publishConfig: { access: "public" },
    },
  },
});

const publicPackage = (dir: string, manifest: Record<string, unknown> = {}): Member => ({
  dir,
  kind: "package",
  manifest: { name: `@acme/${path.basename(dir)}`, version: "0.0.0", ...manifest },
  buildConfig: buildConfigFragment,
});

const editedManifest = (snap: Snapshot, dir: string) => {
  const edit = planSync(snap, path).edits.find((e) => e.path === `${dir}/package.json`);
  return edit === undefined ? undefined : JSON.parse(edit.contents);
};

describe("planSync", () => {
  it("derives publishConfig.exports from exports, mapping src .ts to dist .js", () => {
    const snap = snapshot(
      publicPackage("packages/foo", {
        exports: {
          "./package.json": "./package.json",
          ".": "./src/index.ts",
          "./*": "./src/*.ts",
          "./internal/*": null,
        },
      }),
    );
    expect(editedManifest(snap, "packages/foo")?.publishConfig.exports).toEqual({
      "./package.json": "./package.json",
      ".": "./dist/index.js",
      "./*": "./dist/*.js",
      "./internal/*": null,
    });
  });

  it("adds a missing ./package.json export, first, to both maps", () => {
    const snap = snapshot(publicPackage("packages/foo", { exports: { ".": "./src/index.ts" } }));
    const manifest = editedManifest(snap, "packages/foo");
    expect(Object.keys(manifest?.exports)).toEqual(["./package.json", "."]);
    expect(Object.keys(manifest?.publishConfig.exports)).toEqual(["./package.json", "."]);
  });

  it("merges the manifest fragment: fragment values win, files keeps package extras", () => {
    const snap = snapshot(
      publicPackage("packages/foo", {
        files: ["AGENTS.md", "dist/**/*.js"],
        scripts: { build: "echo hand-edited", test: "vitest" },
      }),
    );
    const manifest = editedManifest(snap, "packages/foo");
    expect(manifest?.scripts).toEqual({ build: "tsc -b tsconfig.build.json", test: "vitest" });
    expect(manifest?.files).toEqual(["AGENTS.md", "dist/**/*.js", "src/**/*.ts"]);
    expect(manifest?.publishConfig.access).toBe("public");
  });

  it("reports an out-of-date manifest as fixable, then nothing once synced", () => {
    const stale = snapshot(publicPackage("packages/foo", { exports: { ".": "./src/index.ts" } }));
    expect(planSync(stale, path).findings).toEqual([
      { path: "packages/foo/package.json", problem: "package.json is out of sync", fixable: true },
    ]);

    const synced = snapshot(publicPackage("packages/foo", editedManifest(stale, "packages/foo")));
    expect(planSync(synced, path)).toEqual({ edits: [], findings: [] });
  });

  it("ignores key order, since the formatter sorts package.json", () => {
    const stale = snapshot(publicPackage("packages/foo", { exports: { ".": "./src/index.ts" } }));
    const synced = editedManifest(stale, "packages/foo");
    const reversed = (value: unknown): unknown =>
      value !== null && typeof value === "object" && !Array.isArray(value)
        ? Object.fromEntries(
            Object.entries(value)
              .reverse()
              .map(([k, v]) => [k, reversed(v)]),
          )
        : value;
    const shuffled = snapshot(
      publicPackage("packages/foo", reversed(synced) as Record<string, unknown>),
    );
    expect(planSync(shuffled, path)).toEqual({ edits: [], findings: [] });
  });

  it("references the build config of each workspace dep and peer dep, sorted, never dev deps", () => {
    const snap = snapshot(
      publicPackage("packages/foo", {
        dependencies: { "@acme/zed": "workspace:*", effect: "catalog:effect" },
        peerDependencies: { "@acme/bar": "workspace:*" },
        devDependencies: { "@acme/dev-only": "workspace:*" },
      }),
      publicPackage("packages/zed"),
      publicPackage("apps/bar"),
      publicPackage("packages/dev-only"),
    );
    const edit = planSync(snap, path).edits.find(
      (e) => e.path === "packages/foo/tsconfig.build.json",
    );
    expect(edit?.contents).toBe(`{
  "extends": "./tsconfig.json",
  "include": ["src"],
  // generated by pkg sync
  "references": [
    { "path": "../../apps/bar/tsconfig.build.json" },
    { "path": "../zed/tsconfig.build.json" }
  ]
}
`);
  });

  it("creates a missing build config from the fragment, even with nothing to reference", () => {
    const snap = snapshot({ ...publicPackage("packages/foo"), buildConfig: undefined });
    const plan = planSync(snap, path);
    expect(plan.edits).toContainEqual({
      path: "packages/foo/tsconfig.build.json",
      contents: buildConfigFragment,
    });
    expect(plan.findings).toContainEqual({
      path: "packages/foo/tsconfig.build.json",
      problem: "tsconfig.build.json is missing",
      fixable: true,
    });
  });

  const privatePackage = (dir: string, extra: Partial<Member> = {}): Member => ({
    dir,
    kind: "package",
    manifest: { name: `@repo/${path.basename(dir)}`, private: true },
    buildConfig: undefined,
    ...extra,
  });

  it("flags a public package depending on a private one, and references only public deps", () => {
    const snap = snapshot(
      publicPackage("packages/foo", { dependencies: { "@repo/secret": "workspace:*" } }),
      privatePackage("packages/secret"),
    );
    const plan = planSync(snap, path);
    expect(plan.findings).toContainEqual({
      path: "packages/foo/package.json",
      problem: "depends on private workspace package @repo/secret",
      fixable: false,
    });
    expect(plan.edits.map((e) => e.path)).not.toContain("packages/foo/tsconfig.build.json");
  });

  it("flags build leftovers on a private package without touching it", () => {
    const leftover = privatePackage("packages/old", { buildConfig: buildConfigFragment });
    const snap = snapshot({
      ...leftover,
      manifest: { ...leftover.manifest, publishConfig: { access: "public" } },
    });
    expect(planSync(snap, path)).toEqual({
      edits: [],
      findings: [
        {
          path: "packages/old/tsconfig.build.json",
          problem: "private package has a build config; delete it or make the package public",
          fixable: false,
        },
        {
          path: "packages/old/package.json",
          problem: "private package has publishConfig; delete it or make the package public",
          fixable: false,
        },
      ],
    });
  });

  it("asks for repo.npmScope only once a public package exists", () => {
    const unscoped = (...members: ReadonlyArray<Member>): Snapshot => {
      const base = snapshot(...members);
      return {
        ...base,
        members: base.members.map((m) =>
          m.kind === "root" ? { ...m, manifest: { name: "monorepo", private: true } } : m,
        ),
      };
    };
    expect(planSync(unscoped(privatePackage("packages/a")), path).findings).toEqual([]);

    const synced = publicPackage(
      "packages/foo",
      editedManifest(snapshot(publicPackage("packages/foo")), "packages/foo"),
    );
    expect(planSync(unscoped(synced), path).findings).toEqual([
      {
        path: "package.json",
        problem: 'public packages exist but "repo": { "npmScope" } is not set',
        fixable: false,
      },
    ]);
    expect(planSync(snapshot(synced), path).findings).toEqual([]);
  });
});
